/** This function is the same as `DetectorPeakResponse::peakResolutionFWHM(...)`, but templated to allow Jets
 TODO: refactor this function and the equivalent `DetectorPeakResponse` function into a single imlpementation.
 */
template<typename T>
T positive_c1_continuation( const T &value, const double floor )
{
  double scalar = 0.0;
  if constexpr ( std::is_same_v<T,double> )
    scalar = value;
  else
    scalar = value.a;
  if( scalar >= floor )
    return value;

  // Equals `value` in both value and derivative at `floor`, stays strictly positive for every
  // finite trial, and approaches zero monotonically as the raw argument tends to -infinity.
  return T(floor*floor) / (T(2.0*floor) - value);
}


template<typename T>
T upper_c1_continuation( const T &value, const T &upper )
{
  double scalar = 0.0, upper_scalar = 0.0;
  if constexpr ( std::is_same_v<T,double> )
  {
    scalar = value;
    upper_scalar = upper;
  }else
  {
    scalar = value.a;
    upper_scalar = upper.a;
  }
  const T join = T(0.5) * upper;
  if( scalar <= 0.5*upper_scalar )
    return value;

  // Exact below half the gamma energy, C1 at the join, and monotonically approaches (but never
  // reaches) `upper`.  Physical detector widths are far below the join; this only regularizes
  // otherwise-invalid optimizer trials.
  const T distance = upper - join;
  return upper - distance*distance / (value - join + distance);
}


template<typename T>
T peakResolutionFWHM( T energy, DetectorPeakResponse::ResolutionFnctForm fcnFrm,
                     const T * const pars, const size_t num_pars )
{
  switch( fcnFrm )
  {
    case DetectorPeakResponse::ResolutionFnctForm::kGadrasResolutionFcn:
    {
      if( num_pars != 3 )
        throw std::runtime_error( "RelActCalcAuto::peakResolutionSigma():"
                                 " pars not defined" );
      const T &a = pars[0];
      const T &b = pars[1];
      const T &c = pars[2];
      
      if( (energy >= 661.0) || (abs(a) < T(1.0E-6)) )
        return 6.61 * b * pow(energy/661.0, c);
      
      if( a < 0.0 )
      {
        const T p = pow( c, T(1.0/log(1.0-a)) );
        return 6.61 * b * pow(energy/661.0, p);
      }//if( a < 0.0 )
      
      if( a > 6.61*b )
        return a;
      
      const T A7 = sqrt( pow(6.61*b, 2.0) - a*a )/6.61;
      return sqrt(a*a + pow(6.61 * A7 * pow(energy/661.0, c), 2.0));
    }//case kGadrasResolutionFcn:
      
    case DetectorPeakResponse::ResolutionFnctForm::kSqrtEnergyPlusInverse:
    {
      if( num_pars != 3 )
        throw std::runtime_error( "RelActCalcAuto::peakResolutionSigma():"
                                 " pars not defined" );
      energy /= PhysicalUnits::keV;
      
      const T width_squared = pars[0] + pars[1]*energy + pars[2]/energy;
      return sqrt( positive_c1_continuation(width_squared, 1.0e-12) );
    }//case kSqrtEnergyPlusInverse:
      
    case DetectorPeakResponse::ResolutionFnctForm::kConstantPlusSqrtEnergy:
    {
      if( num_pars != 2 )
        throw std::runtime_error( "RelActCalcAuto::peakResolutionSigma():"
                                 " pars not defined" );
      energy /= PhysicalUnits::keV;
      
      return pars[0] + pars[1]*sqrt(energy);
    }//case kConstantPlusSqrtEnergy:
      
    case DetectorPeakResponse::ResolutionFnctForm::kSqrtPolynomial:
    {
      if( num_pars < 1 )
        throw runtime_error( "RelActCalcAuto::peakResolutionSigma():"
                            " pars not defined" );
      
      energy /= PhysicalUnits::MeV;
      //return  A1 + A2*std::pow( energy + A3*energy*energy, A4 );

      // Use Horner's method to evaluate the polynomial - more stable.
      T val = pars[num_pars - 1];
      for( int i = static_cast<int>(num_pars) - 2; i >= 0; i -= 1 )
        val = val * energy + pars[i];

#ifndef NDEBUG
      T unstable_val(0.0);
      for( size_t i = 0; i < num_pars; ++i )
        unstable_val += pars[i] * pow(energy, static_cast<double>(i) );
      const T diff = abs(unstable_val - val);
      assert( (diff < 1.0E-4) || (diff < 1.0E-3*max(abs(unstable_val), abs(val))) );
#endif

      return sqrt( positive_c1_continuation(val, 1.0e-12) );
    }//case kSqrtPolynomial:
      
    case DetectorPeakResponse::ResolutionFnctForm::kNumResolutionFnctForm:
      throw std::runtime_error( "RelActCalcAuto::peakResolutionSigma():"
                               " Resolution not defined" );
      break;
  }//switch( m_resolutionForm )
  
  //Lets keep MSVS happy
  assert(0);
  return T(0.0);
}//static T peakResolutionFWHM(...)


/** Berstein polynomial FWHM function.
 *
 * @param energy The energy in keV
 * @param pars The parameters: [berstein_coeffs..., min_energy, max_energy]
 * @param num_pars The number of parameters (berstein coeffs + 2 for min/max energy)
 */
template<typename T>
T bersteinPeakResolutionFWHM( T energy, const T * const pars, const size_t num_pars )
{
  if( num_pars < 4 )
    throw std::runtime_error( "bersteinPeakResolutionFWHM(): insufficient parameters" );
  
  const size_t num_berstein_coeffs = num_pars - 2;
  const T min_energy = pars[num_berstein_coeffs];
  const T max_energy = pars[num_berstein_coeffs + 1];
  
  //assert( energy >= min_energy );
  //assert( energy <= max_energy );

  // Check energy bounds and clamp if necessary
  if( energy < min_energy )
  {
    // This can happen for really large skew peaks so there are peaks from well outside the ROI range
    //  contributing to the peak.
    //  Here we will clamp the value of the scalar, but keep the derivative information, which creates a derivative 
    //  discontinuity at the boundary, but this should be small and rare.
    //  TODO: We could probably do a little better job of preventing this from happening, but its not the biggest fish to fry atm
    if constexpr ( std::is_same_v<T, double> )
      energy = min_energy;
    else
      energy.a = min_energy.a;
  }
  
  if( energy > max_energy )
  {
    if constexpr ( std::is_same_v<T, double> )
      energy = max_energy;
    else
      energy.a = max_energy.a;
  }
  
  // Normalize energy to [0, 1] for Berstein polynomial.
  //  Guard the degenerate window max_energy <= min_energy: otherwise (max-min)==0 gives t = 0/0 = NaN,
  //  which propagates to a NaN FWHM/sigma and aborts the whole cost evaluation.  This happens when a
  //  solve reaches here with an uninitialized FWHM energy range (min==max==0); rather than poison the
  //  fit, fall back to the low-energy control point (t=0) so the FWHM stays finite and the solve can
  //  proceed (and be judged on its merits).  In the normal (max>min) case this is exactly the old path.
  const T t = (max_energy > min_energy) ? ((energy - min_energy) / (max_energy - min_energy)) : T(0);

  // Evaluate Berstein polynomial using the optimized implementation
  return sqrt( BersteinPolynomial::evaluate( t, pars, num_berstein_coeffs ) );
}//T bersteinPeakResolutionFWHM( energy, pars, num_pars )

  
template<typename T>
T eval_fwhm( const T energy, const FwhmForm form, const T * const pars, const size_t num_pars, const shared_ptr<const DetectorPeakResponse> &drf )
{
  DetectorPeakResponse::ResolutionFnctForm fctntype = DetectorPeakResponse::kNumResolutionFnctForm;
  switch( form )
  {
    case RelActCalcAuto::FwhmForm::Gadras:
      fctntype = DetectorPeakResponse::ResolutionFnctForm::kGadrasResolutionFcn;
      break;
      
    case RelActCalcAuto::FwhmForm::SqrtEnergyPlusInverse:
      fctntype = DetectorPeakResponse::ResolutionFnctForm::kSqrtEnergyPlusInverse;
      break;
      
    case RelActCalcAuto::FwhmForm::ConstantPlusSqrtEnergy:
      fctntype = DetectorPeakResponse::ResolutionFnctForm::kConstantPlusSqrtEnergy;
      break;
      
    case RelActCalcAuto::FwhmForm::Polynomial_2:
    case RelActCalcAuto::FwhmForm::Polynomial_3:
    case RelActCalcAuto::FwhmForm::Polynomial_4:
    case RelActCalcAuto::FwhmForm::Polynomial_5:
    case RelActCalcAuto::FwhmForm::Polynomial_6:
      fctntype = DetectorPeakResponse::ResolutionFnctForm::kSqrtPolynomial;
      break;

    case RelActCalcAuto::FwhmForm::Berstein_2:
    case RelActCalcAuto::FwhmForm::Berstein_3:
    case RelActCalcAuto::FwhmForm::Berstein_4:
    case RelActCalcAuto::FwhmForm::Berstein_5:
    case RelActCalcAuto::FwhmForm::Berstein_6:
      // Handle Berstein polynomials directly without using fctntype
      return bersteinPeakResolutionFWHM( energy, pars, num_pars );

    case RelActCalcAuto::FwhmForm::NotApplicable:
      assert( drf && drf->isValid() && drf->hasResolutionInfo() );
      if( !drf || !drf->hasResolutionInfo() )
        throw runtime_error( "RelActCalcAuto::eval_fwhm(): invalid detector response function - how did we get here???" );
      
      const std::vector<float> &drf_coefs = drf->resolutionFcnCoefficients();
      const size_t num_drf_coefs = drf_coefs.size();
      const DetectorPeakResponse::ResolutionFnctForm fwhm_form = drf->resolutionFcnType();
      
      // Note 20260615: all paths (double or Jet) are now being evaluated through same code path to avoid
      //   numeric inconsistencies with using the (possibly slightly faster) float-based method of FWHM eval
      T local_val;
      if( num_drf_coefs < 7 )
      {
        T local_pars[6]; //Avoid allocation overhead of std::vector
        for( size_t i = 0; i < num_drf_coefs; ++i )
          local_pars[i] = T( static_cast<double>(drf_coefs[i]) );
        local_val = peakResolutionFWHM( energy, fwhm_form, local_pars, num_drf_coefs );
      }else
      {
        //Dont expect to ever get here
        vector<T> local_pars( num_drf_coefs );
        for( size_t i = 0; i < num_drf_coefs; ++i )
          local_pars[i] = T( static_cast<double>(drf_coefs[i]) );
        local_val = peakResolutionFWHM( energy, fwhm_form, local_pars.data(), num_drf_coefs );
      }//if( num_drf_coefs < 7 ) / else

#if( PERFORM_DEVELOPER_CHECKS )
      double energy_scalar, local_val_scalar;
      if constexpr ( std::is_same_v<T, double> ) { energy_scalar = energy;   local_val_scalar = local_val; }
      else                                       { energy_scalar = energy.a; local_val_scalar = local_val.a; }
      const float drf_val = drf->peakResolutionFWHM( static_cast<float>(energy_scalar) );
      const double diff = fabs(drf_val - local_val_scalar);
      assert( (diff < 1.0E-4*std::max(local_val_scalar,1.0*drf_val)) || (diff < 1.0E-8) );
#endif

      return local_val;
  }//switch( m_options.fwhm_form )

  assert( fctntype != DetectorPeakResponse::kNumResolutionFnctForm );
  if( fctntype == DetectorPeakResponse::kNumResolutionFnctForm )
    throw runtime_error( "eval_fwhm: invalid FwhmForm" );
  
  //return
  T answer = peakResolutionFWHM( energy, fctntype, pars, num_pars );
  answer = positive_c1_continuation( answer, 1.0e-6 );
  answer = upper_c1_continuation( answer, energy );

  if( isnan(answer) || isinf(answer) )
    throw runtime_error( "eval_fwhm: inf/NaN result." );
  
  if constexpr ( !std::is_same_v<T, double> )
  {
    assert( answer.a > 0.0 );
    assert( answer.a < energy.a );
  }else
  {
    assert( answer > 0.0 );
    assert( answer < energy );
  }
  
#ifndef NDEBUG
  float energy_kev;
  double energy_scalar, answer_scalar;
  vector<float> drf_pars;

  if constexpr ( !std::is_same_v<T, double> )
  {
    energy_scalar = energy.a;
    answer_scalar = answer.a;
    energy_kev = static_cast<float>( energy.a );
    for( size_t i = 0; i < num_pars; ++i )
      drf_pars.push_back( static_cast<float>(pars[i].a) );
  }else
  {
    energy_scalar = energy;
    answer_scalar = answer;
    energy_kev = static_cast<float>( energy );
    for( size_t i = 0; i < num_pars; ++i )
      drf_pars.push_back( static_cast<float>(pars[i]) );
  }

  // `answer` has been through the two C1 continuations that keep an optimizer trial inside
  //  (0, energy), while the DRF reference is the raw form.  Put the reference through the same two
  //  maps before comparing: otherwise any trial that legitimately triggers a continuation - routine
  //  early in a fit, where the raw form goes negative or exceeds the gamma energy - reads as an
  //  order-unity disagreement and aborts a debug build.  Both maps are contractions outside their
  //  join (|f(a)-f(b)| <= |a-b|), so applying them can only tighten this check, never mask a real
  //  mismatch.
  double drf_answer = DetectorPeakResponse::peakResolutionFWHM( energy_kev, fctntype, drf_pars );
  drf_answer = positive_c1_continuation( drf_answer, 1.0e-6 );
  drf_answer = upper_c1_continuation( drf_answer, energy_scalar );

  // The reference is evaluated from float-cast energy and parameters (~6e-8 relative each), and the
  //  sqrt-of-a-sum FWHM forms amplify that wherever their terms cancel, so the tolerance has to be
  //  relative rather than the absolute 0.01 keV it used to lead with.  1e-4 matches the sibling
  //  float-vs-double check in the NotApplicable branch above.
  const double fwhm_diff = fabs( answer_scalar - drf_answer );
  assert( (fwhm_diff < 1.0E-4*(std::max)(fabs(answer_scalar), fabs(drf_answer)))
          || (fwhm_diff < 1.0E-8) );
#endif

  return answer;
}//T eval_fwhm( const T energy, const FwhmForm form, ... )


void RoiRange::toXml( ::rapidxml::xml_node<char> *parent ) const
{
  using namespace rapidxml;

  assert( parent );
  if( !parent || !parent->document() )
    throw runtime_error( "RoiRange::toXml: invalid parent." );

  xml_document<char> *doc = parent->document();
  xml_node<char> *base_node = doc->allocate_node( node_element, "RoiRange" );
  parent->append_node( base_node );

  append_version_attrib( base_node, RoiRange::sm_xmlSerializationVersion );

  append_float_node( base_node, "LowerEnergy", lower_energy );
  append_float_node( base_node, "UpperEnergy", upper_energy );

  const char *cont_type_str = PeakContinuum::offset_type_str( continuum_type );
  append_string_node( base_node, "ContinuumType", cont_type_str );

  // Write new format (preferred)
  const char *range_type_str = RoiRange::to_str( range_limits_type );
  append_string_node( base_node, "RangeLimitType", range_type_str );

  // Also write old format for backward compatibility with older code
  const bool compat_force_full = (range_limits_type == RangeLimitsType::Fixed);
  const bool compat_allow_expand = (range_limits_type == RangeLimitsType::CanExpandForFwhm);

  append_bool_node( base_node, "ForceFullRange", compat_force_full );
  append_bool_node( base_node, "AllowExpandForPeakWidth", compat_allow_expand );
}//RoiRange::toXml(...)


void RoiRange::fromXml( const rapidxml::xml_node<char> *range_node )
{
  try
  {
    if( !range_node )
      throw runtime_error( "invalid input" );

    if( !rapidxml::internal::compare( range_node->name(), range_node->name_size(), "RoiRange", 8, false ) )
      throw std::logic_error( "invalid input node name" );

    // A reminder double check these logics when changing RoiRange::sm_xmlSerializationVersion
    static_assert( RoiRange::sm_xmlSerializationVersion == 0,
                  "needs to be updated for new serialization version." );

    check_xml_version( range_node, RoiRange::sm_xmlSerializationVersion );

    lower_energy = get_float_node_value( range_node, "LowerEnergy" );
    upper_energy = get_float_node_value( range_node, "UpperEnergy" );

    const rapidxml::xml_node<char> *cont_type_node = XML_FIRST_NODE( range_node, "ContinuumType" );
    const string cont_type_str = SpecUtils::xml_value_str( cont_type_node );
    continuum_type = PeakContinuum::str_to_offset_type_str( cont_type_str.c_str(), cont_type_str.size() );

    // Try to read new format first (preferred)
    const rapidxml::xml_node<char> *range_type_node = XML_FIRST_NODE( range_node, "RangeLimitType" );
    if( range_type_node )
    {
      // New format is present
      const string range_type_str = SpecUtils::xml_value_str( range_type_node );
      range_limits_type = RoiRange::range_limits_type_from_str( range_type_str.c_str() );
    }
    else
    {
      // Fall back to old format (for backward compatibility)
      const rapidxml::xml_node<char> *force_full_node = XML_FIRST_NODE( range_node, "ForceFullRange" );
      const rapidxml::xml_node<char> *allow_expand_node = XML_FIRST_NODE( range_node, "AllowExpandForPeakWidth" );

      if( !force_full_node || !allow_expand_node )
        throw runtime_error( "\"RangeLimitType\" node not present" );

      const bool force_full_range = get_bool_node_value( range_node, "ForceFullRange" );
      const bool allow_expand_for_peak_width = get_bool_node_value( range_node, "AllowExpandForPeakWidth" );

      // Validate old format
      if( force_full_range && allow_expand_for_peak_width )
        throw runtime_error( "Both ForceFullRange and AllowExpandForPeakWidth cannot be true" );

      // Convert from old boolean format to new enum
      if( force_full_range )
      {
        range_limits_type = RangeLimitsType::Fixed;
      }
      else if( allow_expand_for_peak_width )
      {
        range_limits_type = RangeLimitsType::CanExpandForFwhm;
      }
      else
      {
        range_limits_type = RangeLimitsType::CanBeBrokenUp;
      }
    }
  }catch( std::exception &e )
  {
    throw runtime_error( "RoiRange::fromXml(): " + string(e.what()) );
  }
}//void fromXml( const ::rapidxml::xml_node<char> *parent )


const std::string NucInputInfo::name() const
{
  if( RelActCalcAuto::is_null(source) )
    return "";

  return RelActCalcAuto::to_name(source);
}//NucInputInfo::name()

bool NucInputInfo::operator==( const NucInputInfo &rhs ) const
{
  return ((this->source == rhs.source) &&
         (this->age == rhs.age) &&
         (this->fit_age == rhs.fit_age) &&
         (this->force_profile_mass_fraction == rhs.force_profile_mass_fraction) &&
         (this->fit_age_min == rhs.fit_age_min) &&
         (this->fit_age_max == rhs.fit_age_max) &&
         (this->min_rel_act == rhs.min_rel_act) &&
         (this->max_rel_act == rhs.max_rel_act) &&
         (this->starting_rel_act == rhs.starting_rel_act) &&
         (this->gammas_to_exclude == rhs.gammas_to_exclude) &&
         (this->peak_color_css == rhs.peak_color_css));
}


bool RoiRange::operator==( const RoiRange &rhs ) const
{
  return (lower_energy == rhs.lower_energy)
    && (upper_energy == rhs.upper_energy)
    && (continuum_type == rhs.continuum_type)
    && (range_limits_type == rhs.range_limits_type);
}

bool RoiRange::operator!=( const RoiRange &rhs ) const
{
  return !( *this == rhs );
}


bool FloatingPeak::operator==( const FloatingPeak &rhs ) const
{
  return (energy == rhs.energy)
    && (release_fwhm == rhs.release_fwhm)
    && (energy_origin == rhs.energy_origin);
}

bool FloatingPeak::operator!=( const FloatingPeak &rhs ) const
{
  return !( *this == rhs );
}


bool RelEffCurveInput::ActRatioConstraint::operator==( const ActRatioConstraint &rhs ) const
{
  return (controlling_source == rhs.controlling_source)
    && (constrained_source == rhs.constrained_source)
    && (constrained_to_controlled_activity_ratio == rhs.constrained_to_controlled_activity_ratio);
}

bool RelEffCurveInput::ActRatioConstraint::operator!=( const ActRatioConstraint &rhs ) const
{
  return !( *this == rhs );
}


bool RelEffCurveInput::MassFractionConstraint::operator==( const MassFractionConstraint &rhs ) const
{
  return (nuclide == rhs.nuclide)
    && (lower_mass_fraction == rhs.lower_mass_fraction)
    && (upper_mass_fraction == rhs.upper_mass_fraction);
}

bool RelEffCurveInput::MassFractionConstraint::operator!=( const MassFractionConstraint &rhs ) const
{
  return !( *this == rhs );
}


bool RelEffCurveInput::PhysModelCorrInput::operator==( const PhysModelCorrInput &rhs ) const
{
  return (corr_fcn == rhs.corr_fcn);
}


bool RelEffCurveInput::operator==( const RelEffCurveInput &rhs ) const
{
  if( (name != rhs.name)
    || (nucs_of_el_same_age != rhs.nucs_of_el_same_age)
    || (rel_eff_eqn_type != rhs.rel_eff_eqn_type)
    || (rel_eff_eqn_order != rhs.rel_eff_eqn_order)
    || (phys_model_corr != rhs.phys_model_corr)
    || (pu242_correlation_method != rhs.pu242_correlation_method)
    || (shielded_by_other_phys_model_curve_shieldings != rhs.shielded_by_other_phys_model_curve_shieldings)
    || (nuclides != rhs.nuclides)
    || (act_ratio_constraints != rhs.act_ratio_constraints)
    || (mass_fraction_constraints != rhs.mass_fraction_constraints) )
  {
    return false;
  }

  // Compare shared_ptr<const PhysicalModelShieldInput> by content
  const bool has_self_lhs = !!phys_model_self_atten;
  const bool has_self_rhs = !!rhs.phys_model_self_atten;
  if( has_self_lhs != has_self_rhs )
    return false;
  if( has_self_lhs && (*phys_model_self_atten != *rhs.phys_model_self_atten) )
    return false;

  if( phys_model_external_atten.size() != rhs.phys_model_external_atten.size() )
    return false;
  for( size_t i = 0; i < phys_model_external_atten.size(); ++i )
  {
    const bool has_lhs = !!phys_model_external_atten[i];
    const bool has_rhs = !!rhs.phys_model_external_atten[i];
    if( has_lhs != has_rhs )
      return false;
    if( has_lhs && (*phys_model_external_atten[i] != *rhs.phys_model_external_atten[i]) )
      return false;
  }

  return true;
}//bool RelEffCurveInput::operator==( const RelEffCurveInput &rhs ) const

bool RelEffCurveInput::operator!=( const RelEffCurveInput &rhs ) const
{
  return !( *this == rhs );
}


